using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Platform;
using PeopleHub.Application.Modules.Requests;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class ApprovalCommentTests
{
 class User(bool admin=true):ICurrentUser{public string Email=>"review@example.local";public int? EmployeeId=>1;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>admin;public bool Can(string p)=>admin;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static WorkflowService Flows(AppDbContext d,User? u=null){u??=new();return new(d,u,new AuditService(d,u,new AppClock(TimeProvider.System)));}
 static ApprovalService Approvals(AppDbContext d){var u=new User();var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,new AccessScope(d,u),u,a,new NotificationService(d,u,c),c,Flows(d),new DelegationService(d,u,a,c));}
 [Fact]public async Task PolicyDefaultsOptionalAndCanBeChangedOnlyByAdmin(){await using var d=await Db();Assert.Empty(await Flows(d).RequiredApprovalCommentsAsync());await Assert.ThrowsAsync<DomainException>(()=>Flows(d,new(false)).SetApprovalCommentAsync("Overtime",true));await Assert.ThrowsAsync<DomainException>(()=>Flows(d).SetApprovalCommentAsync("Unknown",true));await Flows(d).SetApprovalCommentAsync("Overtime",true);Assert.Contains("Overtime",await Flows(d).RequiredApprovalCommentsAsync());await Flows(d).SetApprovalCommentAsync("Overtime",false);Assert.Empty(await Flows(d).RequiredApprovalCommentsAsync());}
 [Fact]public async Task RequiredCommentGuardsPendingApprovalAndIsRetained(){await using var d=await Db();var r=new OvertimeRequest{EmployeeId=6,Date=new(2026,12,1),Hours=2,Multiplier=1.5m,Reason="Fictional",Route="HRManager"};d.Add(r);await d.SaveAsync();await Flows(d).SetApprovalCommentAsync("Overtime",true);var svc=Approvals(d);await Assert.ThrowsAsync<DomainException>(()=>svc.ApproveAsync("Overtime",r.Id," "));Assert.Equal(RequestStatus.Pending,(await d.Set<OvertimeRequest>().FindAsync(r.Id))!.Status);Assert.False(await d.Set<ApprovalAction>().AnyAsync(x=>x.Kind=="Overtime"&&x.RequestId==r.Id));await svc.ApproveAsync("Overtime",r.Id,"  Evidence checked  ");Assert.Equal("Evidence checked",(await d.Set<ApprovalAction>().SingleAsync(x=>x.Kind=="Overtime"&&x.RequestId==r.Id)).Comment);Assert.Equal(RequestStatus.Approved,(await d.Set<OvertimeRequest>().FindAsync(r.Id))!.Status);var row=Assert.Single((await svc.ListAsync("Overtime",RequestStatus.Approved,false)).Where(x=>x.Id==r.Id));Assert.True(row.ApprovalCommentRequired);Assert.Single(row.History);}
 [Fact]public async Task OptionalApprovalAcceptsNoCommentButRejectionStillRequiresReason(){await using var d=await Db();var r=new OvertimeRequest{EmployeeId=6,Date=new(2026,12,1),Hours=2,Multiplier=1.5m,Route="HRManager"};d.Add(r);await d.SaveAsync();var svc=Approvals(d);await Assert.ThrowsAsync<DomainException>(()=>svc.RejectAsync("Overtime",r.Id,null));await svc.ApproveAsync("Overtime",r.Id,null);Assert.Equal(RequestStatus.Approved,(await d.Set<OvertimeRequest>().FindAsync(r.Id))!.Status);}
}
